function login(){ toLogin(); }

// ===== 登录头辅助 =====
function getHeaderMap(_){
	var src = (_ && _.source) ? _.source : source;
	var infomap = "";
	try{ infomap = String(src.getLoginHeader()).replace(/^#/,''); }catch(e){}
	infomap = (infomap!="null"&&infomap!=""&&infomap!=null)?infomap:"{}";
	try{ return JSON.parse(infomap); }catch(e){ return {}; }
}
function setHeaders(){
	var map = getHeaderMap(this);
	for(var i=0;i<arguments.length;i++){
		var k = String(arguments[i]).split("=")[0];
		var v = String(arguments[i]).split("=")[1];
		map[k] = v;
	}
	source.putLoginHeader("#"+JSON.stringify(map));
}
// ===== 登录 =====
function toLogin(){
	try{
		var url = "https://lucifer-club.com/login.php";
		try{ cookie.setCookie(url,""); }catch(e){}
		java.longToast("请在打开的网页中登录，登录完成后点右上角✓");
		try{
			java.startBrowserAwait(url,"登录露西弗俱乐部");
			var co = "";
			for(var i=0;i<5;i++){
				try{ co = String(cookie.getCookie(url)); }catch(e){}
				if(co && co.indexOf("lnfo") >= 0) break;
				try{ java.sleep(300); }catch(e){}
			}
			if(co && co.indexOf("lnfo") >= 0){
				try{ setHeaders("cookie="+encodeURIComponent(co)); }catch(e){}
				try{ cookie.setCookie(url, co); }catch(e){}
				var ok = false;
				try{
					var chk = String(java.ajax("https://lucifer-club.com/my_favorite.php") || "");
					ok = chk.indexOf("luf_forget") < 0 && chk.indexOf("书架列表") >= 0;
				}catch(e){}
				if(ok){
					try{ source.refreshExplore(); }catch(e){}
					java.longToast("✅ 登录成功！请下拉刷新【发现】页（我的收藏/分类）");
				}else{
					java.longToast("⚠️ Cookie 已保存但未生效，请再点一次登录重试");
				}
			}else{
				java.longToast("⚠️ 未检测到登录状态，请重新登录");
			}
		}catch(e){
			java.longToast("登录未完成，请重新尝试");
		}
	}catch(e){
		java.longToast("登录失败："+e);
	}
}
function logoff(){
	try{
		try{ java.ajax("https://lucifer-club.com/login.php?action=logoff"); }catch(e){}
		try{ cookie.removeCookie("https://lucifer-club.com"); }catch(e){}
		java.toast("已退出登录");
	}catch(e){ java.toast("退出失败："+e); }
}

// ===== 交流QQ群（点击申请入群）=====
function joinQQGroup(){
	var u = "mqqapi://card/show_pslcard?src_type=internal&version=1&card_type=group&uin=1097919737";
	try{
		java.openUrl(u);
		java.toast("已尝试打开QQ，若未跳转请手动搜索群号 1097919737");
	}catch(e){
		java.longToast("请手动在QQ中搜索群号 1097919737");
	}
}

// ===== 检查登录状态 =====
function checkLogin(){
	try{
		var co = String(cookie.getCookie("https://lucifer-club.com"));
		if(co.indexOf("lnfo") < 0){
			java.longToast("❌ 未登录：请先点「👤 登录/重新登录」");
			return;
		}
		var m = co.match(/lnfo=([^;]+)/);
		var name = "";
		if(m){
			try{
				var s = java.base64Decode(decodeURIComponent(m[1]));
				var um = String(s).match(/s:\d+:"([^"]+)"/);
				name = um ? um[1] : "";
			}catch(e){}
		}
		if(name){
			java.longToast("✅ 已登录，当前账号：「" + name + "」");
		}else{
			java.longToast("✅ 已登录（Cookie有效）");
		}
	}catch(e){
		java.toast("检查登录状态失败：" + e);
	}
}

ruleBookInfo.intro:
@js:function fmt(h){
	var s=String(h||'');
	s=s.replace(/<br\s*\/?\s*>/gi,'\n').replace(/<\/p>/gi,'\n').replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"');
	s=s.replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').replace(/^\s+|\s+$/g,'');
	return s;
}
var quotes=String(src).match(/<li class="luf_book_quote">[\s\S]*?<\/li>/g)||[];
var cont='';
if(quotes.length){
	cont+='📖【作品简介】\n'+fmt(quotes[0]);
	if(quotes.length>1&&fmt(quotes[1]).length>0){
		cont+='\n📝【絮言絮语】\n'+fmt(quotes[1]);
	}
}
function cleanT(h){return String(h).replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();}
function cleanC(h){return String(h).replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();}
function parseC(html,arr,cap){
	var blks=String(html).match(/<ul class="luf_comment">[\s\S]*?<\/ul>/g)||[];
	for(var i=0;i<blks.length&&arr.length<cap;i++){
		var b=blks[i];
		var tm=b.match(/<li class="luf_comment_title">([\s\S]*?)<\/li>/);
		var cm=b.match(/<li class="luf_comment_contents">([\s\S]*?)<\/li>/);
		if(!tm||!cm)continue;
		var t=cleanT(tm[1]).replace(/《\s+/g,'《').replace(/\s+》/g,'》').replace(/\s+说/g,'说');
		var c=cleanC(cm[1]);
		if(t&&c)arr.push({'t':t,'c':c});
	}
}
function maxPage(html){
	var pg=String(html).match(/<div class="pages">([\s\S]*?)<\/div>/);
	if(!pg)return 1;
	var ns=pg[1].match(/page=(\d+)/g)||[];
	var mx=1;
	for(var i=0;i<ns.length;i++){var n=Number((String(ns[i]).match(/\d+/)||[])[0]||1);if(n>mx)mx=n;}
	return mx;
}
var cmts=[];
var note='';
var bid=(baseUrl.match(/novel-(\d+)/)||[])[1];
try{
	if(bid){
		var p1=String(java.ajax("https://lucifer-club.com/novel.php?id="+bid+"&morecomment=1&page=1")||'');
		parseC(p1,cmts,100);
		var mp=maxPage(p1);
		if(mp>1){
			note=" / 共"+mp+"页";
			if(cmts.length<100){
				try{
					var p2=String(java.ajax("https://lucifer-club.com/novel.php?id="+bid+"&morecomment=1&page=2")||'');
					parseC(p2,cmts,100);
				}catch(e){}
			}
		}
	}
}catch(e){}
if(cmts.length<1){parseC(src,cmts,10);}
if(cmts.length){
	cont+="\n\n💬 书评（显示"+cmts.length+"条"+note+"）：\n";
	for(var i=0;i<cmts.length;i++){
		cont+="🌺 "+cmts[i].t+"\n"+cmts[i].c+"\n\n";
	}
}
result=cont;

